{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; omission does not establish that it did or did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score cannot establish consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring define a narrow grid-puzzle comparison. The 70% describes the reported run, but repeatability and the conditions needed for fair comparisons are insufficiently documented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "A single evaluation supplies no evidence of stability; it does not demonstrate instability either."
        }
      ],
      "instrument_review": "Reporting clearly documents the absence of repeated testing. Exact-grid scoring supports interpreting the single result on these puzzles, but score consistency remains untested."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations explicitly held the stated conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability definition of at most two percentage points."
        }
      ],
      "instrument_review": "Controlled repetitions support consistency under the reported conditions and stated threshold. This evidence concerns these puzzles and settings; it does not establish consistency on other tasks or under changed conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage explicitly documents repeated testing under matching conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed variation exceeds the report's stability limit of two percentage points."
        }
      ],
      "instrument_review": "Repeated testing documents a consistency problem under the stated conditions. The single 70% result cannot adequately represent the reported variation, which limits confidence in comparisons based on one run."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance does not document repeated evaluation."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence of score consistency."
        }
      ],
      "instrument_review": "Installation instructions help explain setup, but do not resolve missing evidence about repeatability. Interpretation remains limited to the reported grid-puzzle run; fair comparisons require adequate evaluation-condition reporting."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher exact-grid result on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison across domains."
        }
      ],
      "instrument_review": "The puzzle set, exact scoring, and fixed instructions support the intended narrow comparison. Repetition and other comparison conditions are unspecified, and the results do not justify a general-intelligence ranking."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better performance by A on these puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broader intended use does not supply evidence about other domains."
        }
      ],
      "instrument_review": "The construction supports a grid-puzzle comparison, but the intended general-intelligence selection extends beyond the supplied evidence. Fixed instructions and exact scoring do not resolve this mismatch or establish repeated-run consistency."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no demonstrated comparison of real workshop decision outcomes."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied setting, with a reported difference interval entirely above zero."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Better decision correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "Preregistration, random allocation, new cases, blinded correctness checks, and reported uncertainty strengthen the comparison for the intended workshop use. Evidence is limited to correctness in one workshop; other settings, time, safety, and repeated-trial consistency remain unestablished."
    }
  ],
  "closing_note": "No material instruction was unclear. Missing evidence was treated as Not established; explicit conflicting evidence was treated as Contradicted."
}
